        "explanation":  "In the above sentence \u0027Swimming\u0027 will be used in place of \u0027 to swim\u0027 because gerund (verb 1 + ing) is used after verb enjoy. Note- Admit, avoid, delay, deny, detest, enjoy, exc use, finish, forgive, mind, prevent, keep, resent, it is no use, it is no good, can\u0027t help, can\u0027t stand etc. always followed by v+ing form. Correct sentence :- Anita enjoyed swimming in the sea."
