        "explanation":  "man tends to one / of the horses after it\u0027s / training at a stud farm. (a) of the horses after it\u0027s (b) A man tends to one (c) No error (d) training at a stud farm SSC MTS-06/07/2022 Shift-II Ans. (a) : In the above sentence, \u0027of the horses after its, will be used instead of \u0027of the horses after it\u0027s\u0027, because in sentence, according to horses, possessive adject ive its\u0027 will be used while \u0027it\u0027s\u0027 is the short form of \u0027it is \u0027. because possessive adjective is used before noun (training). Correct Sentence – A man tends to one of the horses after its training at a stud farm."
