        "explanation":  "In the above sentence, \u0027we would have\u0027 will be used instead of \u0027we will have\u0027 because the sente nce is in conditional sentence and in the first clause of conditional sentence- Had + V 3 and in second clause would have + V 3 is used. Note - Had + Subject + V 3 + Other word + Subject + Would/Could/Might + have + V 3 + Other word. Correct Sentence - Had you not reached in time we would have lost our lives."
